  33→export const loader = async ({ request }: LoaderFunctionArgs) => {
  34→  const { session } = await authenticate.admin(request);
  35→  const shop = session.shop;
  36→
  37→  let config = await db.widgetConfig.findUnique({ where: { shop } });
  38→
  39→  if (!config) {
  40→    config = await db.widgetConfig.create({ data: { shop } });
  41→  }
  42→
  43→  const subscription = await getShopSubscription(shop);
  44→
  45→  return { config, subscription };
  46→};
