 300→// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
 301→function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
 302→  if (!rawCss) return "";
 303→  const css = rawCss.replace(/<\/style>/gi, "");
 304→  let result = "";
 305→  let remaining = css;
 306→  while (remaining.length > 0) {
 307→    const openBrace = remaining.indexOf("{");
 308→    if (openBrace === -1) break;
 309→    const closeBrace = remaining.indexOf("}", openBrace);
 310→    if (closeBrace === -1) break;
 311→    const selector = remaining.substring(0, openBrace).trim();
 312→    const body = remaining.substring(openBrace + 1, closeBrace);
 313→    remaining = remaining.substring(closeBrace + 1);
 314→    if (selector.startsWith("@")) {
 315→      result += selector + "{" + body + "}";
 316→    } else if (selector) {
 317→      const prefixed = selector.split(",").map(s => {
 318→        s = s.trim();
 319→        return s ? "#" + wid + " " + s : "";
 320→      }).filter(Boolean).join(", ");
 321→      result += prefixed + " {" + body + "}";
 322→    }
 323→  }
 324→  return result;
 325→}
